\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}

\begin{document}

\pagestyle{empty}

\begin{tikzpicture}

\begin{axis}[
trig format plots=rad,
legend pos=outer north east,
tick label style={font=\footnotesize},
label style={font=\small},
legend style={font=\footnotesize},
tick style={draw=none},
axis line style = thick,
axis y line = center,
axis x line = middle,
%axis equal,
%grid = both,
xmin = -14,
xmax = 6,
ymin = -3,
ymax = 6,
xtick = {-10},
ytick = {2},
xticklabels = {$-10$},
yticklabels = {$2$},
%minor xtick={-10,-8,...,10},
%minor ytick={-10,-8,...,10},
xlabel = $z$,
ylabel = $u$,
xlabel style={below right},
ylabel style={above right},
% Here, we control the position of individual tick marks
y tick label style={xshift={(\tick==2)*14pt}},
every axis x label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=west,
},
every axis y label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=south,
}
]

% Graphics
\addplot [domain=-14:14,samples=300,color=red,line width=1pt]{(-1/5)*x};

% Segments
\draw [line width=1pt,black,dashed,opacity=0.3] (axis cs: -10,0) -- (axis cs: -10,2) -- (axis cs: 0,2);

% Dots
\node[circle,draw=none,fill=blue,inner sep=1.5pt] at (axis cs: -10,2) {};

\end{axis}

\end{tikzpicture}
\end{document}
